// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    uint256 public callCount;

    function setUp() public {
        c = new SimpleWallet();
        callCount = 0;
    }

    function testFuzz_property(uint256 amount, uint8 times) public {
        amount = bound(amount, 1 wei, 10 ether);
        times = uint8(bound(times, 1, 100));

        vm.deal(address(this), amount * times + 100 ether);

        for (uint8 i = 0; i < times; i++) {
            bytes memory data;
            (bool ok,) = address(c).call{value: amount}(data);
            require(ok, "receive failed");
        }

        assertTrue(c.depositsCount() == times);
    }
}
